import re

# Read input bytes (e.g., from stdin or as argument)
m_bytes_path = '/home/ctfplayer/m_bytes.bin'
with open(m_bytes_path, 'rb') as f:
    m_bytes = f.read()

pattern = re.compile(rb'csawctf\{[^}]+}')
found = []
# 256-byte string, window is len of typical flag or less
for start in range(len(m_bytes)):
    for end in range(start+10, min(start+64, len(m_bytes)+1)):
        substr = m_bytes[start:end]
        m = pattern.match(substr)
        if m:
            found.append((start, m.group().decode(errors='replace')))

if found:
    print("Flags found:")
    for offset, flag in found:
        print(f"Offset {offset}: {flag}")
else:
    print("No matches for csawctf flag regex in m_bytes")
